exempt = (input('exempt_assets') || {})['CKV_AWS_321'] || []

control 'CKV_AWS_321' do
  title 'Ensure Redshift clusters use enhanced VPC routing'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_redshift_cluster resources that actually exist, read through the
    stock inspec-aws aws_redshift_cluster resource.
  DESC

  desc 'rationale', <<~RATIONALE
    Without enhanced VPC routing, COPY and UNLOAD traffic leaves through the
    public endpoint, where VPC controls and flow logs do not see it.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_redshift_cluster: enhanced_vpc_routing is True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_redshift_cluster:

      resource "aws_redshift_cluster" "example" {
        enhanced_vpc_routing = true
      }

    Out of band — aws_redshift_cluster:

      aws redshift modify-cluster --cluster-identifier <id> --enhanced-vpc-routing
  FIX

  tag checkov_id:            'CKV_AWS_321'
  tag checkov_category:      'GENERAL_SECURITY'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_redshift_cluster]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/redshift_cluster#enhanced-vpc-routing'
  tag nist:                  ['SC-7', 'AC-4']
  tag nist_r4:               ['SC-7', 'AC-4']
  tag cci:                   ['CCI-001097']
  tag ksi:                   ['KSI-CNA-NDS']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'reviewed'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
